    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int d = 0; d <= 9; d++) {
        long next = (long) current * 10 + d;
        if (next > n) {
            break; // further digits will only increase the value
        }
        dfs((int) next, n, result);
    }
}

